{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF mixture weight",
      "description": "A weighting parameter that linearly combines model-based and model-free action values at Stage 1.",
      "params": [
        {
          "name": "w",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_stickiness",
      "title": "Stage 1 choice stickiness",
      "description": "A general tendency to repeat the Stage 1 action chosen on the previous trial, regardless of the outcome.",
      "params": [
        {
          "name": "stickiness",
          "bounds": [
            -5,
            5
          ]
        }
      ],
      "evidence": "bonus_1[last_action_1] += stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_reward_stickiness",
      "title": "Stage 1 reward-dependent stickiness",
      "description": "An additional tendency to repeat the previous Stage 1 action specifically if it led to a reward on the previous trial.",
      "params": [
        {
          "name": "reward_stickiness",
          "bounds": [
            -5,
            5
          ]
        }
      ],
      "evidence": "bonus_1[last_action_1] += reward_stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "stage_2_action_stickiness",
      "title": "Stage 2 action stickiness",
      "description": "A motor persistence tendency to repeat the same Stage 2 action from the previous trial, regardless of which second-stage state (planet) is visited.",
      "params": [
        {
          "name": "action_2_stickiness",
          "bounds": [
            -5,
            5
          ]
        }
      ],
      "evidence": "bonus_2[last_action_2] += action_2_stickiness",
      "expressible_in_slots": true
    }
  ]
}
